(()=>{
const id=document.body.dataset.lesson,c=window.CATALOG.find(x=>x.id===id);let step=0,playing=false,timer=null,p={};
const hints={uptake:['养分存在于土壤溶液中。','质流、扩散等过程使养分到达根表。','离子通过膜上的通道或转运蛋白进入根细胞。','养分进入木质部，随水分运向地上部。'],minimum:['先把各养分供给换算为相对满足度。','相对最不足的养分，成为当前的限制因子。','只补氮，不能解除磷不足造成的限制。','提高短板后，限制因子可能发生转移。'],nitrogen:['有机氮是土壤氮库的重要组成部分。','矿化将部分有机氮转化为铵态氮。','硝化将铵态氮经亚硝态氮转化为硝态氮。','植物可吸收铵态氮和硝态氮；氮也可能淋失或气态损失。'],blocks:['肥力存在梯度，直接比较可能混入环境差异。','沿梯度分层，让同一区组内条件尽量相近。','每个区组内独立随机，且包含全部处理。','在多个区组重复，比较处理并控制区组差异。'],interaction:['两个因素：氮水平 × 磷水平，共四个处理组合。','两条线平行：该模型中氮效应不随磷水平改变。','两条线不平行：氮效应随磷水平而改变。','交互对比为零表示可加；是否显著还需重复与误差估计。']};
document.title=`${c.title} · 植知互动教学`;document.querySelector('h1').textContent=c.title;document.querySelector('.category').textContent=c.category;document.querySelector('.question p').textContent=c.question;
const nav=document.querySelector('.steps');c.steps.forEach((s,i)=>{const b=document.createElement('button');b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${s}`;b.onclick=()=>{stop();setStep(i)};nav.append(b)});
const controls=document.querySelector('.param-controls'),scene=document.querySelector('.scene');
function slider(name,label,min,max,val){const l=document.createElement('label');l.innerHTML=`${label}<input type="range" min="${min}" max="${max}" step="1" value="${val}" aria-label="${label}"><output>${val}</output>`;const input=l.querySelector('input'),out=l.querySelector('output');input.oninput=()=>{stop();p[name]=Number(input.value);out.textContent=input.value;render()};controls.append(l);p[name]=val;return input}
let sliders={};if(id==='minimum'){sliders.n=slider('n','氮 N',10,100,80);sliders.p=slider('p','磷 P',10,100,35);sliders.k=slider('k','钾 K',10,100,70)}
if(id==='interaction')sliders.effect=slider('effect','交互强度',-25,25,0);
if(id==='blocks'){let b=document.createElement('button');b.textContent='重新随机 ↻';b.onclick=()=>{stop();p.rows=Array.from({length:3},()=>shuffle([0,1,2,3]));step=2;render()};controls.append(b)}
if(id==='uptake'||id==='nitrogen')controls.innerHTML='<span class="static-note">沿着路径，观察养分的去向。</span>';
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function sync(name,v){p[name]=v;let s=sliders[name];if(s){s.value=v;s.nextElementSibling.textContent=v}}
function setStep(n){step=Math.max(0,Math.min(c.steps.length-1,n));if(id==='minimum'){[[80,35,70],[80,35,70],[100,35,70],[90,90,90]][step].forEach((v,i)=>sync(['n','p','k'][i],v))}if(id==='interaction')sync('effect',[0,0,20,20][step]);render()}
function render(){scene.innerHTML=PlantScenes[id](p,step);nav.querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('active',i===step);b.setAttribute('aria-current',i===step?'step':'false')});document.querySelector('.caption').textContent=hints[id][step];document.querySelector('#progress').textContent=`${step+1} / ${c.steps.length}`;document.querySelector('#prev').disabled=step===0;document.querySelector('#next').disabled=step===c.steps.length-1;scene.querySelector('svg').setAttribute('aria-label',`${c.steps[step]}：${hints[id][step]}`);if(!playing)pauseMotion()}
function pauseMotion(){scene.querySelector('svg')?.pauseAnimations?.()}
function stop(){playing=false;clearInterval(timer);timer=null;document.querySelector('#play').textContent='▶ 演示';document.querySelector('#play').setAttribute('aria-pressed','false');pauseMotion()}
function play(){if(playing){stop();return}playing=true;if(step===c.steps.length-1)setStep(0);document.querySelector('#play').textContent='Ⅱ 暂停';document.querySelector('#play').setAttribute('aria-pressed','true');scene.querySelector('svg')?.unpauseAnimations?.();timer=setInterval(()=>{if(step===c.steps.length-1){stop();return}setStep(step+1);scene.querySelector('svg')?.unpauseAnimations?.()},6500)}
document.querySelector('#play').onclick=play;document.querySelector('#prev').onclick=()=>{stop();setStep(step-1)};document.querySelector('#next').onclick=()=>{stop();setStep(step+1)};document.querySelector('#reset').onclick=()=>{stop();p.rows=undefined;setStep(0)};document.querySelector('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{document.querySelector('#fullscreen').textContent='请按 F11'}};
document.addEventListener('keydown',e=>{if(['INPUT','BUTTON','A'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){stop();setStep(step+1);e.preventDefault()}if(e.key==='ArrowLeft'){stop();setStep(step-1);e.preventDefault()}if(e.code==='Space'){play();e.preventDefault()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});setStep(0);
})();
